<?php
require_once __DIR__.'/../bootstrap/app.php';use GymPro\Services\AttendanceService;require_any_role('RECEPTIONIST','SUPER_ADMIN');$u=current_user();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{if(($_POST['action']??'')==='check_in')AttendanceService::checkIn((int)$_POST['member_id'],(int)$u['UserID']);else AttendanceService::checkOut((int)$_POST['visit_id'],(int)$u['UserID']);set_flash('success','Reception attendance updated.');redirect('reception/index.php');}catch(Throwable $e){$errors[]=$e->getMessage();}}
$q=trim($_GET['q']??'');$members=$q!==''?db_all("SELECT m.MemberID,m.MemberNumber,m.Name,m.Email,u.Status AccountStatus,s.Status SubscriptionStatus,s.EndsAt,p.AllowsGymAccess,(SELECT GymAttendanceID FROM GYM_ATTENDANCE g WHERE g.MemberID=m.MemberID AND g.Status='CHECKED_IN' AND g.CheckOutAt IS NULL LIMIT 1) OpenVisit FROM MEMBER m LEFT JOIN USER_ACCOUNT u ON u.MemberID=m.MemberID LEFT JOIN SUBSCRIPTION s ON s.SubscriptionID=(SELECT s2.SubscriptionID FROM SUBSCRIPTION s2 WHERE s2.MemberID=m.MemberID ORDER BY s2.SubscriptionID DESC LIMIT 1) LEFT JOIN MEMBERSHIP_PLAN p ON p.PlanID=s.PlanID WHERE m.MemberNumber LIKE CONCAT('%',?,'%') OR m.Name LIKE CONCAT('%',?,'%') OR m.Email LIKE CONCAT('%',?,'%') LIMIT 20",'sss',[$q,$q,$q]):[];$inside=db_all("SELECT g.GymAttendanceID,g.CheckInAt,m.Name,m.MemberNumber FROM GYM_ATTENDANCE g JOIN MEMBER m ON m.MemberID=g.MemberID WHERE g.Status='CHECKED_IN' AND g.CheckOutAt IS NULL ORDER BY g.CheckInAt DESC");$pageTitle='Reception check-in';$pageSubtitle='Validate membership before recording gym entry';include ROOT_PATH.'/includes/header.php';?>
<?php if($errors):?><div class="alert alert-danger"><?=e(implode(' ',$errors))?></div><?php endif;?><form class="hero-search" method="get"><label for="q">Find a member</label><div><input id="q" name="q" value="<?=e($q)?>" placeholder="Member number, name, or Gmail address" autofocus><button class="btn btn-primary">Search</button></div></form>
<?php if($q!==''):?><div class="table-wrap"><table class="data-table"><thead><tr><th scope="col">Member</th><th scope="col">Account</th><th scope="col">Membership</th><th scope="col">Gym access</th><th scope="col">Action</th></tr></thead><tbody><?php foreach($members as $m):?><tr><td><strong><?=e($m['Name'])?></strong><br><small><?=e($m['MemberNumber'])?> · <?=e($m['Email'])?></small></td><td><?=e($m['AccountStatus']??'NO ACCOUNT')?></td><td><?=e($m['SubscriptionStatus']??'NONE')?><?=$m['EndsAt']?'<br><small>to '.e(date('d M Y',strtotime($m['EndsAt']))).'</small>':''?></td><td><span class="badge <?=$m['AllowsGymAccess']?'badge-green':'badge-red'?>"><?=$m['AllowsGymAccess']?'Allowed':'Not allowed'?></span></td><td><form method="post"><?=csrf_field()?><?php if($m['OpenVisit']):?><input type="hidden" name="visit_id" value="<?=$m['OpenVisit']?>"><button class="btn btn-ghost" name="action" value="check_out">Check out</button><?php else:?><input type="hidden" name="member_id" value="<?=$m['MemberID']?>"><button class="btn btn-success" name="action" value="check_in">Check in</button><?php endif;?></form></td></tr><?php endforeach;if(!$members):?><tr><td colspan="5" class="empty-state">No matching members.</td></tr><?php endif;?></tbody></table></div><?php endif;?>
<div class="section-header section-spaced"><h2 class="section-title">Currently checked in</h2><span class="badge badge-blue"><?=count($inside)?> inside</span></div><div class="card-grid compact"><?php foreach($inside as $v):?><article class="visit-card"><div><strong><?=e($v['Name'])?></strong><small><?=e($v['MemberNumber'])?> · since <?=e(date('H:i',strtotime($v['CheckInAt'])))?></small></div><form method="post"><?=csrf_field()?><input type="hidden" name="visit_id" value="<?=$v['GymAttendanceID']?>"><button class="btn btn-ghost btn-sm" name="action" value="check_out">Check out</button></form></article><?php endforeach;?></div>
